#include "uart_workbench.h"
#include "uart_tool_form.h"
#include "uart_files.h"
#include "settings_fields.h"
#include <cmath>
void UartWorkbench::framing_dialog(size_t i){auto& g=groups_[i];const auto current=g.framer.config();const std::vector<std::wstring> modes={L"Read chunks",L"LF",L"CRLF",L"Fixed bytes",L"Idle receipt gap",L"Header + fixed bytes"};const auto convert=[&modes](const std::vector<std::wstring>& f,TrafficFraming& c,std::wstring& error){c.mode=static_cast<TrafficFraming::Mode>(std::find(modes.begin(),modes.end(),f[0])-modes.begin());double bytes=0,idle=0;if(!uart_number(f[1],1,65536,bytes)||bytes!=std::floor(bytes)||!uart_number(f[2],1,60000,idle)||idle!=std::floor(idle)){error=L"Frame bytes 1..65536; idle 1..60000 ms, whole numbers.";return false;}c.bytes=static_cast<size_t>(bytes);c.idle_ms=static_cast<unsigned>(idle);if(!f[3].empty()){TxEntry entry{f[3],true,TxEnding::None};if(!make_tx_payload(entry,c.header,error))return false;}TrafficFramer check;std::string detail;if(!check.configure(c,detail)){error=uart_wide(detail);return false;}return true;};
    UartToolForm form(i?L"Packet inspection - Port B":L"Packet inspection - Port A",L"Assembles RX and accepted TX separately across reads. Idle framing uses PC receipt gaps, not guaranteed UART wire gaps. Header framing has a fixed total length; variable length/checksums belong in Binary parser. Apply clears only the inspection rows and starts with new incoming bytes. Raw ASCII/HEX/recording stay unchanged. Framing preferences are saved in the portable INI/workspace.",{{L"Framing",modes[current.mode],modes},{L"Total frame bytes",std::to_wstring(current.bytes)},{L"Idle gap (ms)",std::to_wstring(current.idle_ms)},{L"Header HEX",uart_wide(uart_hex(current.header))}},{},[convert](const auto& f,std::wstring& error){TrafficFraming c;return convert(f,c,error);},this);
    if(form.DoModal()!=IDOK||shutdown_)return;TrafficFraming selected;std::wstring error;if(!convert(form.values(),selected,error)){warn(error);return;}const auto encoded=pack_settings({std::to_wstring(selected.mode),std::to_wstring(selected.bytes),std::to_wstring(selected.idle_ms),uart_wide(uart_hex(selected.header))});if(!WritePrivateProfileStringW(i?L"Workbench.Framing.B":L"Workbench.Framing.A",L"Configuration",encoded.c_str(),ini_.c_str())){warn(L"Cannot save framing; previous configuration retained.");return;}std::string detail;if(!g.framer.configure(std::move(selected),detail)){warn(uart_wide(detail));return;}g.packets.clear();g.packet_bytes=0;g.mode=2;::SendMessageW(g.view,CB_SETCURSEL,2,0);g.dirty=true;update_view(i);}
